from pathlib import Path
import json,csv
import pandas as pd
from reportlab.lib.pagesizes import letter
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import inch
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib.utils import ImageReader

ROOT=Path(__file__).resolve().parent
M=json.loads((ROOT/'results/metrics.json').read_text(encoding='utf-8'))
cross=pd.read_csv(ROOT/'results/crossfade_experiment.csv')
lat=pd.read_csv(ROOT/'results/test_sentences.csv')
pdfmetrics.registerFont(TTFont('Arial','C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('Arial-Bold','C:/Windows/Fonts/arialbd.ttf'))
S=getSampleStyleSheet()
S.add(ParagraphStyle(name='T',fontName='Arial-Bold',fontSize=22,leading=26,textColor=colors.HexColor('#15324B'),spaceAfter=5))
S.add(ParagraphStyle(name='H',fontName='Arial-Bold',fontSize=15,leading=18,textColor=colors.HexColor('#15324B'),spaceBefore=3,spaceAfter=5))
S.add(ParagraphStyle(name='H2',fontName='Arial-Bold',fontSize=10.5,leading=13,textColor=colors.HexColor('#286A8A'),spaceBefore=3,spaceAfter=3))
S.add(ParagraphStyle(name='B',fontName='Arial',fontSize=8.2,leading=10.5,textColor=colors.HexColor('#28303A'),spaceAfter=4))
S.add(ParagraphStyle(name='C',fontName='Arial',fontSize=7.2,leading=8.5,textColor=colors.HexColor('#28303A')))
S.add(ParagraphStyle(name='CH',fontName='Arial-Bold',fontSize=7.2,leading=8.5,textColor=colors.white))
S.add(ParagraphStyle(name='Cap',fontName='Arial',fontSize=7.5,leading=9,textColor=colors.HexColor('#5F6973'),alignment=TA_CENTER,spaceAfter=3))
def P(x,style='B'):return Paragraph(x,S[style])
def T(head,rows,widths=None):
    data=[[P(str(x),'CH') for x in head]]+[[x if hasattr(x,'drawOn') else P(str(x),'C') for x in r] for r in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='CENTER')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#15324B')),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#CCD5DD')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F2F5F8')]),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)]));return t
def I(name,w):
    path=ROOT/'results/figures'/name; iw,ih=ImageReader(str(path)).getSize();return Image(str(path),width=w*inch,height=w*inch*ih/iw)
def footer(c,d):
    c.saveState();c.setFont('Arial',7);c.setFillColor(colors.HexColor('#60717F'));c.drawString(.6*inch,.32*inch,'CSE457 | Lab 4 Mini TTS');c.drawRightString(7.9*inch,.32*inch,str(d.page));c.restoreState()
story=[P('Lab 4 Mini TTS','T'),P('Báo cáo thực hành CSE457 | Tổng hợp tiếng nói'),P('Pipeline dùng inventory, unit selection, cross-fade, prosody, HMM-state parameters và neural VITS để sinh câu thông báo xếp hàng. Inventory có 16 nhãn; queue case chạy qua cả ba backend waveform. MOS chủ quan vẫn cần người nghe chấm.'),P('1. Inventory và phạm vi dữ liệu','H')]
story += [P('Nguồn có bảy từ lệnh: bật, dừng, lên, phải, trái, tắt, xuống. Dataset gốc bị copy byte trong từng nhãn nên năm candidate lấy từ dataset_aug/. Đó là biến thể augmentation, không phải năm lần thu tự nhiên. Chín từ thiếu của câu queue được tạo thành hai biến thể mỗi từ bằng Meta MMS VITS tiếng Việt. Metadata ghi rõ nguồn recording hoặc model.'),P(f"Inventory cuối gồm {M['inventory_label_count']} nhãn với {M['candidate_recording_count']} WAV. Câu mẫu đã được normalize và chạy qua các backend; unit tổng hợp không được mô tả như bản thu người nói độc lập.")]
story += [I('inventory_stats.png',5.7),P('Hình 1. Phân bố duration và RMS sau trim.','Cap'),P('normalize_text() viết thường, bỏ dấu câu, đọc từng chữ số; “23” thành “hai ba”.'),T(['ID','Câu','Tokens'],[[r.id,r.text,r.tokens] for r in lat.itertuples()],[.45*inch,2.8*inch,3.5*inch]),PageBreak()]
story += [P('2. Ghép nối và unit selection','H'),P('Baseline lấy candidate 01 cho mỗi token, không cross-fade, lưu raw_concat.wav. Target cost là z-score duration và log-RMS so với thống kê của nhãn. Join cost so sánh log-magnitude spectrum hai cửa sổ 25 ms, cộng 12 lần chênh log-RMS. Dynamic programming tìm chuỗi có target + join cost nhỏ nhất.')]
summary=pd.read_csv(ROOT/'results/unit_selection_summary.csv')
story += [T(['Câu','Cách chọn','Tổng join cost'],[[r.utterance,r.method,f'{r.total_join_cost:.1f}'] for r in summary.itertuples()],[1.1*inch,2.4*inch,1.3*inch]),P(f"Trên queue sentence, đường tối ưu trùng candidate đầu nên cost không đổi. Trên S1 command, DP giảm join cost {M['command_join_reduction_percent']:.1f}%. Khi chỉ tối ưu join, có thể chọn phổ khớp nhưng sai target/context."),I('unit_selection_costs.png',5.7),P('Hình 2. Join cost giữa candidate pairs ở từng boundary của queue.','Cap'),P('Cross-fade dùng ramp tuyến tính chồng 0, 5, 15 hoặc 30 ms. Bảng cộng tỉ lệ sample-jump và energy-jump so với baseline no-fade.')]
story += [T(['Fade','Sample jump','Energy jump','Chỉ số'],[[f'{r.crossfade_ms} ms',f'{r.mean_sample_jump:.5f}',f'{r.mean_energy_jump:.3f}',f'{r.combined_discontinuity_proxy:.3f}'] for r in cross.itertuples()],[1.0*inch,1.35*inch,1.35*inch,1.2*inch]),P(f"Chọn {M['crossfade_chosen_ms']} ms theo combined proxy. Fade dài có thể làm mờ phụ âm; lựa chọn này dựa trên hai continuity measures, không phải MOS."),I('boundary_comparison.png',5.7),P('Hình 3. Waveform/spectrogram gần boundary của queue.','Cap'),PageBreak()]
story += [P('3. Prosody và source-filter','H'),P(f"F0 trung vị unit len là {M['median_f0_hz']:.1f} Hz. Tại Fs=16 kHz, F0=Fs/Np cho Np xấp xỉ {M['pitch_period_samples']} mẫu. YIN loại frame năng lượng thấp. Duration thử 0.8x, 1.0x, 1.2x; pitch thử -2, 0, +2 semitone. Trong source-filter, F0 thuộc excitation tuần hoàn, còn formant chủ yếu thuộc spectral envelope của vocal tract; thay F0 không đồng nghĩa dịch formant."),P('TD-PSOLA đổi khoảng cách giữa các đoạn quanh pitch epoch rồi overlap-add. Kéo dài voiced fricative quá mức có thể lặp excitation tuần hoàn trên thành phần nhiễu và tạo buzziness. Cross-fade quá dài chồng burst/transition nên làm phụ âm kém rõ.'),I('prosody_f0_pitch.png',5.7),P('Hình 4. F0 và đáp ứng phổ tương đối ở các mức pitch shift.','Cap'),P('4. HMM state-parameter generation','H'),P('Mỗi từ chia thành 5 state; CSV lưu mean F0, RMS, spectral centroid và duration. HMM state path trái-sang-phải sinh trajectory. Đây là state-parameter demo theo yêu cầu Lab, không phải model tham số đã huấn luyện đầy đủ. hmm_tts.wav là hybrid: duration state điều khiển time-stretch trên waveform thu thật, không có vocoder.'),I('hmm_tracks.png',5.5),P('Hình 5. F0 và spectral-centroid trajectory theo state.','Cap'),P('Concatenative phát lại waveform tự nhiên, phụ thuộc inventory/context. Parametric HMM sinh trajectory từ state distribution, dễ điều khiển hơn nhưng model nhỏ có thể nghe robotic. Delta features ràng buộc biến thiên giữa frame để trajectory trơn hơn.'),PageBreak()]
story += [P('5. So sánh backend và listening evaluation','H'),P('Waveform comparison dùng cùng câu queue. Boundary metrics đo continuity; text-to-unit lookup xác nhận coverage nhưng không thay thế listener test. ratings.csv để trống chờ MOS/naturalness/intelligibility thực.'),T(['Backend','Intelligibility','Naturalness','Continuity','Latency/status'],[['Concatenative','Unit coverage; listening pending','Chưa rating','Boundary metrics',f"{lat[lat.id=='QUEUE'].generation_latency_s.iloc[0]:.3f} s"],['HMM hybrid','Cùng token units','Chưa rating','Audio + plots','Hybrid, không full vocoder'],['Neural MMS VITS','Sinh trực tiếp từ text','Chưa rating','Waveform/mel',f"{M['neural_latency_s']['QUEUE']:.3f} s inference"]],[1.0*inch,1.35*inch,1.05*inch,1.1*inch,1.8*inch]),P('Đã chạy checkpoint facebook/mms-tts-vie của Meta qua Transformers/PyTorch local-only; model tạo waveform 16 kHz cho ba test phrases và queue. Model card: huggingface.co/facebook/mms-tts-vie; Pratap et al. (2023), arXiv:2305.13516. Weights ở local cache, không đóng gói project. License CC-BY-NC 4.0: chỉ dùng phi thương mại và giữ attribution. Latency excludes model-load time.'),I('backend_comparison.png',5.1),P('Hình 6. Raw, unit-selection, HMM hybrid và neural MMS VITS.','Cap'),I('neural_queue_mel.png',5.1),P('Hình 7. Mel-spectrogram neural VITS của queue sentence.','Cap'),PageBreak(),P('6. Câu hỏi phân tích','H')]
qa=[('1. Đoạn tự nhiên vẫn kém tự nhiên?','Khác speaker, accent, F0, level, coarticulation, timing hoặc prosody; cắt sai biên tạo discontinuity.'),('2. Target cost và join cost?','Target đo phù hợp unit-vị trí; join đo êm giữa hai unit. Chỉ join có thể ghép êm nhưng sai từ/context.'),('3. Cross-fade dài làm mờ phụ âm?','Trộn burst/transition lâu và có thể triệt tiêu tín hiệu do phase khác nhau.'),('4. F0 và formant?','F0 là chu kỳ excitation; formant do cộng hưởng vocal tract. Pitch shift lý tưởng thay excitation, không dịch formant.'),('5. PSOLA và buzziness?','Di chuyển các window quanh pitch epoch với chu kỳ mới rồi overlap-add; kéo voiced fricative dài gây lặp tuần hoàn trên nhiễu.'),('6. Delta làm trajectory trơn?','Delta biểu diễn đạo hàm feature; dynamic objective giới hạn bước nhảy giữa frame/state.'),('7. Vì sao cần inventory lớn?','Cần unit đa dạng theo ngữ cảnh, speaker, tốc độ và biên nối để vừa đúng target vừa tự nhiên.'),('8. Concatenative và neural?','Concatenative lắp waveform lưu sẵn; neural dự đoán acoustic/vocoder từ text, linh hoạt hơn nhưng cần model/dữ liệu/tài nguyên.'),('9. Vì sao không tải model tùy ý?','Model, version, voice, device khác nhau làm chất lượng và latency không tái lập, không công bằng.'),('10. MOS cao, intelligibility thấp?','Có thể dùng ambient/background không cần hiểu nội dung; không phù hợp cảnh báo hay hướng dẫn.')]
story += [P('<b>'+q+'</b> '+a) for q,a in qa]
story += [P('Kết luận và giới hạn','H2'),P('Pipeline đã sinh 16 labels, 53 WAV candidates, queue raw/best/HMM hybrid/neural output, cross-fade, prosody, state tracks, latency và bảy hình. Việc còn lại là listening test thực với người nghe để đo MOS, naturalness, continuity chủ quan và intelligibility; không thể suy ra trung thực từ waveform statistics.'),P('Chạy lại: `python lab4.py` từ LAB4 sau khi cài requirements.txt và cache checkpoint một lần bằng `python prepare_neural_tts.py`.')]
doc=SimpleDocTemplate(str(ROOT/'Bao_cao_Lab4.pdf'),pagesize=letter,leftMargin=.55*inch,rightMargin=.55*inch,topMargin=.48*inch,bottomMargin=.52*inch,title='Lab 4 Mini TTS',author='CSE457 Lab')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
